CREATE TABLE IF NOT EXISTS model_routes(route_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,capability TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,cost_class TEXT NOT NULL,policy_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS provider_health(provider TEXT PRIMARY KEY,state TEXT NOT NULL,consecutive_failures INTEGER NOT NULL,latency_p95_ms INTEGER NOT NULL,checked_at TEXT NOT NULL);